// src/data/cpi.ts
export const cpi: CpiData;
export function getSlotYears(): number[]; // 최신 5개 연도, 오름차순
export function getLatestCpiYear(): number; // L
// src/lib/types.ts
export type LoadResult = { ok: true; entries: SalaryEntry[] } | { ok: false };

export function calculate(entries: SalaryEntry[], cpi: CpiData, currentYear: number): AppResult;
// nominal = S_b/S_a − 1; real = (1+nominal)/Π_{t=a+1..b}(1+r_t/100) − 1 (% 단위로 저장)
// cumulativeReal = S_last/(S_first×Π_{first+1..last}) − 1
// L = max(rates.year), n = max(0, Y−L)
// A = ceilMan(S_last×Π_{last+1..L}×1.02^n), B = ceilMan(S_first×Π_{first+1..L}×1.02^n) (원 = 만원×10000)
// targetWon = max(A,B); requiredRaisePct = (targetMan/S_last − 1)×100
export function parseAmountInput(raw: string): AmountInputResult;
export function validateAmount(amountMan: number): boolean; // 정수 1~100000
export function formatSignedPct(pct: number): string; // '+5.0%' | '−3.3%'

